<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import type { ToastObject } from './create-toast-manager.js'; import { ToastItemState, getToastProviderContext, setToastItemContext } from './toast-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLLIElement>, 'children' | 'title'> { children?: Snippet<[ToastObject]>; toast: ToastObject; ref?: HTMLLIElement | null; } let { children, toast, ref = $bindable(null), ...rest }: Props = $props(); const provider = getToastProviderContext(); const item = setToastItemContext(new ToastItemState()); $effect.pre(() => { item.toast = toast; item.index = provider.toasts.findIndex((candidate) => candidate.id === toast.id); });</script><li bind:this={ref} {...rest} role={toast.priority === 'high' ? 'alert' : 'status'} aria-live={toast.priority === 'high' ? 'assertive' : 'polite'} data-type={toast.type} data-limited={toast.limited ? '' : undefined} data-starting={toast.transitionStatus === 'starting' ? '' : undefined} style:--toast-index={item.index}>{@render children?.(toast)}</li>
